import routes from '@config/user-preferences/pref-routes'
import publicSections from '@src/config/user-preferences/sections'
import i18n from '@src/i18n/i18n.js'
let entSections = {}

const onlyNotifications =
  new URLSearchParams(window.location.search).get('onlyNotifications') === 'true'

const subscriptionSection = {
  title: `${i18n.t('Subscription')}`,
  faIcon: 'fas fa-money-check',
  importComponent: () => import('@entSrc/components/user-preferences/SubscriptionPreferences'),
  route: routes.Subscription,
  isHidden: onlyNotifications,
}
const detectiveHoursSection = {
  title: `${i18n.t('AI Detection Hours')}`,
  faIcon: 'fas fa-hourglass-half',
  importComponent: () => import('@entSrc/components/user-preferences/DetectiveHours'),
  route: routes.DetectiveHours,
  isHidden: onlyNotifications,
}
const deleteAccountSection = {
  title: `${i18n.t('Delete Account')}`,
  faIcon: 'fas fa-trash-alt',
  importComponent: () => import('@entSrc/components/user-preferences/DeleteAccount'),
  route: routes.DeleteAccount,
  isHidden: onlyNotifications,
}

for (const [key, value] of Object.entries(publicSections)) {
  // insert Subscription section right before Athorized Apps
  if (key === 'AuthorizedApps') {
    entSections.Subscription = subscriptionSection
    entSections.DetectiveHours = detectiveHoursSection
  }
  entSections[key] = value
}

// reinsurance: if Authorized Apps will gone, instert Subscription at the end
if (!entSections.Subscription) {
  entSections.Subscription = subscriptionSection
  entSections.DetectiveHours = detectiveHoursSection
}

entSections.DeleteAccount = deleteAccountSection

export default entSections
import notificationPlugins from '@src/notifications/plugins'

const defaultRoutes = {
  GeneralPreferences: '/user_preferences/general/',
  ThemePreferences: '/user_preferences/personalization/',
  ProfilePreferences: '/user_preferences/profile/',
  AuthorizedApps: '/user_preferences/authorized_apps/',
  GeneralNotifications: '/user_preferences/general_notifications/',
  PushNotifications: '/user_preferences/mobile_push_notifications/',
}

const notificationRoutes = Object.keys(notificationPlugins).reduce((obj, name) => {
  return Object.assign(obj, { [name]: `/user_preferences/notification_${name}/` })
}, {})

export default {
  ...defaultRoutes,
  ...notificationRoutes,
}

