  const shot = async (name) => { await page.waitForTimeout(300); const p = `${out}/${name}.png`; await page.screenshot({ path: p }); shots.push(p); };
  await shot('6-signed-in-account-details');
  await page.evaluate(() => { window.sent = []; const post = window.wx.postMessage; window.wx.postMessage = (j) => { window.sent.push(JSON.parse(j)); return post(j); }; });
  await page.getByRole('button', { name: 'Open in browser' }).click();
  const sent = await page.evaluate(() => window.sent.map((m) => [m.type, m.payload]));
  await page.evaluate(() => window.fake.scene('payg', 'dark'));
  await shot('7-signed-in-dark');
  await page.evaluate(() => { window.fake.scene('payg', 'light'); window.fake.deliver('setup_keys', { keys: [] }); });
  await page.setViewportSize({ width: 800, height: 640 });
  await shot('8-signed-out');
  return { shots, contentHeight: h, sent };
})(page);
