#pragma once

#include "AgentService.hpp"
#include "AgentSetup.hpp"

#include <functional>
#include <memory>
#include <string>

namespace Slic3r { class AppConfig; }

namespace Slic3r::GUI::JusPrin::Agent {

class IChatModelSource;

struct AgentRuntime
{
    AgentServicePtr      service;
    AgentAvailability    availability{AgentAvailability::Unavailable};
    std::string          provider;
    std::string          unavailable_reason;
    // Verifies and stores credentials entered in the Agent dock. Always
    // present: setup is what an unconfigured build offers.
    AgentSetupServicePtr setup;
};

// Reads the Agent's choices and provider key from AppConfig. Project/recovery
// state never receives credentials.
AgentRuntime load_agent_runtime(AppConfig* config);

// Shared provider credential lookup for bounded, non-conversational features
// such as printer recognition. The key is an AppConfig item, "<provider>_api_key"
// in the Agent section, rather than an OS credential-store entry: macOS asks
// for the login password whenever a differently signed build reads a Keychain
// entry, which every unsigned rebuild is.
std::string load_provider_api_key(const AppConfig* config, const std::string& provider);

// The setup service the Agent dock drives: it verifies a candidate key
// against the live provider and, on success, stores it and records the
// non-secret choices load_agent_runtime() reads on the next launch.
AgentSetupServicePtr make_agent_setup(AppConfig* config);

// Signing in to a JusPrin account: the account is stored where the Agent's
// keys are, and signing in makes it the Agent's provider.
CloudSignInPtr make_cloud_sign_in(AppConfig* config);
// Where "Get more credits" goes, on the server the account signs in to.
std::string cloud_pricing_url(const AppConfig* config);
// The server's "Forgot password" page.
std::string cloud_password_reset_url(const AppConfig* config);// Where a print report goes, and the account's token; empty when signed out.
std::string cloud_print_reports_url(const AppConfig* config);
std::string cloud_account_token(const AppConfig* config);

// The docked Agent's per-chat models: every provider with a stored key, the
// default provider setup recorded, agents built from those keys, and each
// provider's model list fetched from the provider. `post` runs a callback on
// the GUI thread; the lists arrive through it.
std::shared_ptr<IChatModelSource> make_chat_model_source(AppConfig* config,
                                                         std::function<void(std::function<void()>)> post);

} // namespace Slic3r::GUI::JusPrin::Agent

// The Agent page in its Preferences mode (?panel=preferences): JusPrin's
// Preferences window. It speaks the same bridge as the Agent panel, so its
// key checks and AI tool connections run on the same host code, and adds one
// message of its own, preferences_action.

import { useEffect, useMemo, useReducer } from 'react';
import { BridgeClient, Transport } from './bridge/client';
import { initialState, reducer } from './state/store';
import { applyAppearance } from './tokens';
import { BridgeErrorPane, ConnectingPane } from './components/Panels';
import { Preferences, PreferencesActions } from './components/Preferences';

export function PreferencesApp({ getTransport }: { getTransport: () => Transport | null }) {
  const [state, dispatch] = useReducer(reducer, initialState);

  const client = useMemo(
    () =>
      new BridgeClient({
        getTransport,
        onConnectionChange: (connection, detail) => dispatch({ kind: 'connection', state: connection, detail }),
        onEnvelope: (envelope) => dispatch({ kind: 'host', envelope }),
      }),
    // The transport is fixed for the lifetime of the page.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [],
  );

  useEffect(() => {
    client.start();
  }, [client]);

  useEffect(() => {
    applyAppearance(state.appearance);
  }, [state.appearance]);

  // Coming back from the browser, where credits may have been bought.
  useEffect(() => {
    const refresh = () => client.send('refresh_account', {});
    window.addEventListener('focus', refresh);
    return () => window.removeEventListener('focus', refresh);
  }, [client]);

  // A window opened for one task closes itself once it is done.
  const closeWhenDone = Boolean(state.preferences?.closeWhenDone);
  const finish = (done: 'key' | 'tool') => client.send('shell_action', { action: 'close', done });
  useEffect(() => {
    if (closeWhenDone && state.setup.phase === 'verified') finish('key');
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [closeWhenDone, state.setup.phase]);

  const actions = useMemo<PreferencesActions>(
    () => ({
      set: (name, value) => client.send('preferences_action', { action: 'set', name, value }),
      run: (action, details) => client.send('preferences_action', { ...details, action }),
      checkKey: (provider, apiKey) => client.send('setup_check_key', { provider, apiKey }),
      cancelCheck: () => client.send('setup_cancel', {}),
      removeKey: (provider) => client.send('setup_remove_key', { provider }),
      refreshTools: () => client.send('mcp_catalog', {}),
      previewTool: (toolId) => client.send('mcp_preview', { toolId }),
      connectTool: (toolId) => client.send('mcp_connect', { toolId }),
      revealTool: (toolId) => client.send('reveal_path', { toolId }),
      signIn: () => client.send('account_sign_in', {}),
      cancelSignIn: () => client.send('account_cancel', {}),
      getMoreCredits: () => client.send('shell_action', { action: 'open_pricing' }),    }),
    [client],
  );

  if (state.connection !== 'connected' && state.connection !== 'connecting') {
    return (
      <div className="app">
        <BridgeErrorPane title="Preferences could not reach JusPrin" detail={state.connectionDetail}
          diagnostics={state.diagnostics} onRetry={() => client.retry()} />
      </div>
    );
  }
  if (!state.preferences) return <div className="app"><ConnectingPane /></div>;

  return (
    <div className="app app--preferences">
      <Preferences
        preferences={state.preferences}
        setup={state.setup}
        savedKeys={state.savedKeys}
        account={state.account}
        creditAccount={state.creditAccount}
        chatTitles={state.chatTitles}
        mcpCatalog={state.mcpCatalog}
        mcpPreview={state.mcpPreview}
        mcpStatus={state.mcpStatus}
        actions={actions}
        onToolDone={closeWhenDone ? () => finish('tool') : undefined}
      />
    </div>
  );
}

